"""Summarize mailbox letters without changing the input tree."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re


NAME = re.compile(r"^[0-9]{8}T[0-9]{4}[-_]")
RESOLVING = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}
REQUIRED = ("id", "from", "to", "status", "at")


def read_letter(path, now):
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeError):
        return None, "no_frontmatter"
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    if any(not fields.get(key) for key in REQUIRED):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields["at"])
    except ValueError:
        return None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)
    if not NAME.match(path.name):
        return None, "bad_name"
    try:
        datetime.strptime(path.name[:13], "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    return {"id": fields["id"], "from": fields["from"],
            "to": fields["to"], "status": fields["status"],
            "re": fields.get("re", ""), "at": at}, None


def summarize(root, now):
    boxes = {}
    files = []
    for box in sorted(root.iterdir(), key=lambda path: path.name):
        if box.name.startswith(".") or box.is_symlink() or not box.is_dir():
            continue
        inbox = box / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[box.name] = {"inbox": {}, "done": 0}
        for where, folder in (("inbox", inbox), ("done", inbox / "done")):
            if folder.is_symlink() or not folder.is_dir():
                continue
            for path in folder.iterdir():
                if (not path.name.startswith(".") and path.name.endswith(".md")
                        and not path.is_symlink() and path.is_file()):
                    files.append((path.relative_to(root).as_posix(), path, box.name, where))

    seen = set()
    letters = []
    bad = []
    for relative, path, box, where in sorted(files):
        letter, why = read_letter(path, now)
        if why is None and letter["id"] in seen:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        seen.add(letter["id"])
        letters.append((letter, box, where))
        if where == "done":
            boxes[box]["done"] += 1
        else:
            counts = boxes[box]["inbox"]
            status = letter["status"]
            counts[status] = counts.get(status, 0) + 1

    resolved = {letter["re"] for letter, _, _ in letters
                if letter["status"] in RESOLVING and letter["re"]}
    open_letters = []
    for letter, _, where in letters:
        if letter["status"] == "REQUEST" and letter["id"] not in resolved:
            open_letters.append({"id": letter["id"], "from": letter["from"],
                                 "to": letter["to"], "where": where,
                                 "age_min": (now - letter["at"]) // timedelta(minutes=1)})
    open_letters.sort(key=lambda item: (item["to"], item["id"]))
    for box in boxes.values():
        box["inbox"] = dict(sorted(box["inbox"].items()))
    return {"v": 1, "open": open_letters, "boxes": boxes,
            "bad": sorted(bad, key=lambda item: (item["file"], item["why"]))}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailbox summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a time zone")
    if now.tzinfo is None:
        parser.error("--now must have a time zone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False,
                     separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
